<script>
import { Head, router } from '@inertiajs/vue3';
import axios from 'axios';
import Card from '@scaffold/components/Card.vue';
import Toggle from '@scaffold/components/Toggle.vue';
import { applyAppearance } from '@scaffold/lib/appearance';
import { update } from '@app/routes/user-settings';
import sidebar1 from '@scaffold-assets/sidebar-1.jpg';
import sidebar2 from '@scaffold-assets/sidebar-2.jpg';
import sidebar3 from '@scaffold-assets/sidebar-3.jpg';
import sidebar4 from '@scaffold-assets/sidebar-4.jpg';
import sidebar5 from '@scaffold-assets/sidebar-5.jpg';

export default {
    components: { Card, Head, Toggle },
    layout: { pageTitle: 'Personīgie iestatījumi' },
    data() {
        return {
            appearanceOptions: [
                { value: 'light', label: 'Gaišs' },
                { value: 'dark', label: 'Tumšs' },
                { value: 'system', label: 'Sistēmas' },
            ],
            highlightOptions: [
                { value: 'primary', label: 'Violets' },
                { value: 'info', label: 'Gaiši zils' },
                { value: 'success', label: 'Zaļš' },
                { value: 'warning', label: 'Oranžs' },
                { value: 'danger', label: 'Sarkans' },
                { value: 'rose', label: 'Rozā' },
            ],
            tintOptions: [
                { value: 'black', label: 'Melns' },
                { value: 'white', label: 'Balts' },
                { value: 'red', label: 'Sarkans' },
            ],
            backgroundImages: [sidebar1, sidebar2, sidebar3, sidebar4, sidebar5],
            selectedPreferences: null,
            saving: false,
            saveError: '',
        };
    },
    computed: {
        preferences() {
            const settings = this.$page.props.auth.user?.settings;
            const background = Number(settings?.background ?? 1);

            return this.selectedPreferences ?? {
                appearance: this.$page.props.appearance ?? 'system',
                highlight: settings?.highlight || 'danger',
                tint: settings?.tint || 'black',
                background: this.backgroundImages[background] ? background : 1,
                show_bg: settings?.show_bg ?? true,
            };
        },
    },
    methods: {
        async setPreference(key, value) {
            if (this.saving || this.preferences[key] === value) {
                return;
            }

            const previousPreferences = this.selectedPreferences;
            const preferences = { ...this.preferences, [key]: value };
            this.selectedPreferences = preferences;
            this.saveError = '';
            this.saving = true;

            try {
                await axios.post(update.url(), { [key]: value });
                if (key === 'appearance') {
                    applyAppearance(value);
                }
                router.reload({ only: ['appearance', 'auth'] });
            } catch {
                this.selectedPreferences = previousPreferences;
                this.saveError = 'Neizdevās saglabāt iestatījumus. Mēģiniet vēlreiz.';
            } finally {
                this.saving = false;
            }
        },
    },
};
</script>

<template>
    <div>
        <Head title="Personīgie iestatījumi" />

        <div class="row justify-content-center">
            <div class="col-12 settings-column">
                <Card>
                    <div class="settings-content" :aria-busy="saving">
                        <fieldset class="settings-section">
                            <legend class="settings-heading">Izskats</legend>
                            <div class="d-flex flex-wrap justify-content-center gap-2">
                                <button
                                    v-for="option in appearanceOptions"
                                    :key="option.value"
                                    type="button"
                                    class="btn-sm theme-primary"
                                    :class="preferences.appearance === option.value ? 'btn-solid' : 'btn-outline'"
                                    :aria-pressed="preferences.appearance === option.value"
                                    :disabled="saving"
                                    @click="setPreference('appearance', option.value)"
                                >
                                    {{ option.label }}
                                </button>
                            </div>
                        </fieldset>

                        <fieldset class="settings-section">
                            <legend class="settings-heading">Navigācijas filtri</legend>
                            <div class="d-flex flex-wrap justify-content-center gap-2">
                                <button
                                    v-for="option in highlightOptions"
                                    :key="option.value"
                                    type="button"
                                    class="badge settings-swatch"
                                    :class="'badge-' + option.value"
                                    :aria-label="option.label"
                                    :aria-pressed="preferences.highlight === option.value"
                                    :disabled="saving"
                                    @click="setPreference('highlight', option.value)"
                                ></button>
                            </div>
                        </fieldset>

                        <fieldset class="settings-section">
                            <legend class="settings-heading">Navigācijas tonis</legend>
                            <div class="d-flex flex-wrap justify-content-center gap-2">
                                <button
                                    v-for="option in tintOptions"
                                    :key="option.value"
                                    type="button"
                                    class="badge settings-swatch"
                                    :class="'settings-swatch-' + option.value"
                                    :aria-label="option.label"
                                    :aria-pressed="preferences.tint === option.value"
                                    :disabled="saving"
                                    @click="setPreference('tint', option.value)"
                                ></button>
                            </div>
                        </fieldset>

                        <div class="settings-section d-flex align-items-center justify-content-between gap-2">
                            <label for="settings-show-background" class="mb-0">Navigācijas fons</label>
                            <Toggle
                                id="settings-show-background"
                                :model-value="preferences.show_bg"
                                :disabled="saving"
                                @update:model-value="setPreference('show_bg', $event)"
                            />
                        </div>

                        <fieldset>
                            <legend class="settings-heading">Attēli</legend>
                            <div class="settings-backgrounds">
                                <button
                                    v-for="(image, index) in backgroundImages"
                                    :key="image"
                                    type="button"
                                    class="settings-background"
                                    :aria-label="'Fona attēls ' + (index + 1)"
                                    :aria-pressed="preferences.background === index"
                                    :disabled="saving"
                                    @click="setPreference('background', index)"
                                >
                                    <img :src="image" alt="" />
                                </button>
                            </div>
                        </fieldset>

                        <p v-if="saveError" class="text-danger mb-0" role="alert">{{ saveError }}</p>
                    </div>
                </Card>
            </div>
        </div>
    </div>
</template>

<style scoped>
    .settings-column {
        max-inline-size: 37rem;
    }

    .settings-content {
        --settings-selection-color: #00b9ee;
        padding-inline: clamp(0rem, 3vw, 1.5rem);
    }

    .settings-section {
        padding-block: 0.625rem 0.875rem;
        margin-block-end: 0.625rem;
        border-block-end: 1px solid var(--border-color-translucent);
    }

    .settings-heading {
        padding: 0;
        margin-block-end: 0.5rem;
        font-size: 0.75rem;
        font-weight: 600;
        text-align: center;
        text-transform: uppercase;
    }

    .settings-swatch {
        flex: none;
        inline-size: 1.0625rem;
        block-size: 1.0625rem;
        min-block-size: 0;
        padding: 0;
        border: 0;
        border-radius: 50%;
        color: inherit;
    }

    .settings-swatch-black { background-color: #000; }
    .settings-swatch-white { background-color: #f1f1f1; }
    .settings-swatch-red { background-color: #f44336; }

    .settings-backgrounds {
        display: grid;
        grid-template-columns: repeat(5, minmax(0, 1fr));
        gap: clamp(0.5rem, 2vw, 1.25rem);
        padding-inline: 0.625rem;
    }

    .settings-background {
        overflow: hidden;
        padding: 0;
        border: 0;
        border-radius: 0.5rem;
    }

    .settings-background img {
        display: block;
        inline-size: 100%;
        aspect-ratio: 1 / 2;
        object-fit: cover;
    }

    button[aria-pressed='true'] {
        outline: 3px solid var(--settings-selection-color);
    }

    button:focus-visible {
        outline: 2px solid currentColor;
        outline-offset: 2px;
    }
</style>
